<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder; use Illuminate\Support\Facades\DB;
class StatusSeeder extends Seeder { public function run(): void { foreach(['Pending','Approved','Rejected','In Progress','On Hold','Completed','Closed'] as $name) DB::table('request_statuses')->updateOrInsert(['status_name'=>$name],['updated_at'=>now(),'created_at'=>now()]); foreach(['Pending','Approved','Assigned','In Progress','On Hold','Completed','Closed'] as $name) DB::table('job_order_statuses')->updateOrInsert(['status_name'=>$name],['updated_at'=>now(),'created_at'=>now()]); foreach(['Pending','Fulfilled','Rejected'] as $name) DB::table('material_request_statuses')->updateOrInsert(['status_name'=>$name],['updated_at'=>now(),'created_at'=>now()]); foreach(['New Request','Request Status Changed','Job Assigned','Material Request','Material Request Update','Low Stock'] as $name) DB::table('notification_types')->updateOrInsert(['type_name'=>$name],['updated_at'=>now(),'created_at'=>now()]); } }
